<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/database.php'; require_once __DIR__ . '/../includes/functions.php'; require_login();
$error=''; if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $action=$_POST['action']??''; $id=filter_input(INPUT_POST,'organizer_id',FILTER_VALIDATE_INT); $name=trim((string)($_POST['organizer_name']??'')); $email=trim((string)($_POST['email']??'')); $phone=trim((string)($_POST['phone']??'')); $organization=trim((string)($_POST['organization']??'')); $address=trim((string)($_POST['address']??'')); try { if($action==='save'){ if($name===''||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))) throw new InvalidArgumentException('Organizer name is required and email must be valid.'); if($id){$s=$pdo->prepare('UPDATE organizers SET organizer_name=?, email=?, phone=?, organization=?, address=? WHERE organizer_id=?');$s->execute([$name,$email,$phone,$organization,$address,$id]);flash('success','Organizer updated successfully.');}else{$s=$pdo->prepare('INSERT INTO organizers (organizer_name,email,phone,organization,address) VALUES (?,?,?,?,?)');$s->execute([$name,$email,$phone,$organization,$address]);flash('success','Organizer added successfully.');}}elseif($action==='delete'&&$id){$s=$pdo->prepare('DELETE FROM organizers WHERE organizer_id=?');$s->execute([$id]);flash('success','Organizer deleted successfully.');} redirect('/event_shit/organizers/organizers.php');}catch(InvalidArgumentException|PDOException $exception){$error=$exception instanceof InvalidArgumentException?$exception->getMessage():'Unable to complete the organizer operation.';}}
$search=trim((string)($_GET['search']??''));$s=$pdo->prepare('SELECT * FROM organizers WHERE organizer_name LIKE ? OR email LIKE ? OR organization LIKE ? ORDER BY organizer_name');$term='%'.$search.'%';$s->execute([$term,$term,$term]);$organizers=$s->fetchAll();$pageTitle='Organizers';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';
?>
<main class="col-md-9 col-lg-10 p-4"><?php require __DIR__.'/../includes/alerts.php'; ?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="d-flex justify-content-between align-items-center mb-4"><h1 class="h3">Organizers</h1><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#organizerModal">+ Add organizer</button></div><form class="row g-2 mb-3"><div class="col-sm-6"><input class="form-control" name="search" value="<?=e($search)?>" placeholder="Search name, email, organization"></div><div class="col-auto"><button class="btn btn-outline-secondary">Search</button></div></form><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Phone</th><th>Organization</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($organizers as $o):?><tr><td><?=$o['organizer_id']?></td><td><?=e($o['organizer_name'])?></td><td><?=e($o['email'])?></td><td><?=e($o['phone'])?></td><td><?=e($o['organization'])?></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#organizerModal" data-id="<?=$o['organizer_id']?>" data-name="<?=e($o['organizer_name'])?>" data-email="<?=e($o['email'])?>" data-phone="<?=e($o['phone'])?>" data-organization="<?=e($o['organization'])?>" data-address="<?=e($o['address'])?>">Edit</button><button class="btn btn-sm btn-outline-danger" data-bs-toggle="modal" data-bs-target="#deleteModal" data-id="<?=$o['organizer_id']?>" data-name="<?=e($o['organizer_name'])?>">Delete</button></td></tr><?php endforeach;?></tbody></table></div></div></main>
<div class="modal fade" id="organizerModal" tabindex="-1"><div class="modal-dialog"><form class="modal-content" method="post"><div class="modal-header"><h2 class="modal-title fs-5">Organizer</h2><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="organizer_id" id="organizer_id"><?php foreach([['organizer_name','Organizer name','text'],['email','Email','email'],['phone','Phone','text'],['organization','Organization','text'],['address','Address','text']] as [$field,$label,$type]):?><label class="form-label"><?=$label?></label><input class="form-control mb-3" name="<?=$field?>" id="<?=$field?>" type="<?=$type?>" <?=$field==='organizer_name'?'required':''?>><?php endforeach;?></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div><div class="modal fade" id="deleteModal" tabindex="-1"><div class="modal-dialog"><form class="modal-content" method="post"><div class="modal-header"><h2 class="modal-title fs-5">Confirm delete</h2><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body">Delete <strong id="delete_name"></strong>?<input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="organizer_id" id="delete_id"></div><div class="modal-footer"><button class="btn btn-secondary" data-bs-dismiss="modal" type="button">Cancel</button><button class="btn btn-danger">Delete</button></div></form></div></div><script>const om=document.getElementById('organizerModal');om.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;['id','name','email','phone','organization','address'].forEach(k=>document.getElementById(k==='id'?'organizer_id':(k==='name'?'organizer_name':k)).value=b.dataset[k]||'')});document.getElementById('deleteModal').addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;document.getElementById('delete_id').value=b.dataset.id;document.getElementById('delete_name').textContent=b.dataset.name});</script><?php require __DIR__.'/../includes/footer.php'; ?>
